func validationSummaryFor(ctx context.Context, db *store.DB, task store.Task, repository string) (validationSummary, error) {
	summary := validationSummary{Head: task.GatedSHA, Review: "unknown", Findings: map[string]int{}, CI: "unknown"}
	plan, err := task.AdmittedPlan()
	if err != nil {
		return summary, err
	}
	if plan != nil {
		summary.Review = plan.Review
		if plan.ValidationLoops != nil && plan.ValidationLoops.Review.Enabled {
			summary.MaxRounds = plan.ValidationLoops.MaxReviewRounds()
		}
	}
	usage, err := db.ReviewCapUsage(ctx, task.ID)
	if err != nil {
		return summary, err
	}
	summary.RoundsUsed, summary.RepairUsed = usage.ReviewRounds, usage.RepairRounds
	rounds, err := db.ReviewRoundsFor(ctx, task.ID)
	if err != nil {
		return summary, err
	}
	for _, round := range rounds {
		if round.Status == "admitted" {
			summary.Pending++
		}
		if round.Verdict != "" {
			summary.LatestVerdict = round.Verdict
		}
		if summary.Head == "" {
			summary.Head = round.HeadSHA
		}
	}
	summary.Remaining = max(0, summary.MaxRounds-reviewCapUsed(task, usage)-summary.Pending)
	findings, err := db.ReviewFindingsForTask(ctx, task.ID)
	if err != nil {
		return summary, err
	}
	for _, finding := range findings {
		state := finding.State
		if finding.InheritedFrom > 0 {
			state = "inherited"
		}
		summary.Findings[state]++
	}
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM review_carries WHERE ship_task_id=?`, task.ID).Scan(&summary.Carries); err != nil {
		return summary, err
	}
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM review_dispositions WHERE ship_task_id=?`, task.ID).Scan(&summary.Dispositions); err != nil {
		return summary, err
	}
	if summary.Head == "" {
		err := db.QueryRowContext(ctx, `SELECT head_sha FROM review_dispositions WHERE ship_task_id=? ORDER BY id DESC LIMIT 1`, task.ID).Scan(&summary.Head)
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return summary, err
		}
	}
	if summary.Head != "" {
		var quote string
		err := db.QueryRowContext(ctx, `SELECT user_quote FROM review_dispositions WHERE ship_task_id=? AND head_sha=? ORDER BY id DESC LIMIT 1`, task.ID, summary.Head).Scan(&quote)
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return summary, err
		}
		if quote != "" {
			summary.Accepted = append(summary.Accepted, "User quote: \""+quote+"\"")
			rows, err := db.QueryContext(ctx, `SELECT f.severity,COALESCE(parent.title,p.title),f.path
FROM review_findings f JOIN review_patterns p ON p.id=f.pattern_id LEFT JOIN review_patterns parent ON parent.id=p.merged_into
WHERE f.ship_task_id=? AND f.head_sha=? AND f.state='accepted' AND (?='' OR f.repository=?)
ORDER BY COALESCE(parent.seq,p.seq),f.seq`, task.ID, summary.Head, repository, repository)
			if err != nil {
				return summary, err
			}
			defer rows.Close()
			for rows.Next() {
				var severity, title, path string
				if err := rows.Scan(&severity, &title, &path); err != nil {
					return summary, err
				}
				summary.Accepted = append(summary.Accepted, fmt.Sprintf("Accepted finding %s: %s (%s)", severity, title, path))
			}
			if err := rows.Err(); err != nil {
				return summary, err
			}
		}
	}
	if task.PRURL != "" {
		observation, err := db.LatestPRObservation(ctx, task.ID)
		switch {
		case err == nil:
			checks := decodeChecks(observation.Checks)
			summary.CI = strings.ToLower(checks.State)
			if len(checks.Failures) > 0 {
				summary.CI = "failed: " + failedCheckNames(checks.Failures)
			}
			if summary.CI == "" {
				summary.CI = "unknown"
			}
		case store.IsNotFound(err):
			summary.CI = "pending"
		default:
			return summary, err
		}
	}
	return summary, nil
}

func (summary validationSummary) findingStates() []string {
	states := make([]string, 0, len(summary.Findings))
	for state := range summary.Findings {
		states = append(states, state)
	}

