251: func (s *Service) refreshPRValidationBlock(ctx context.Context, db *store.DB, project store.Project, task store.Task, forge repositoryForge, prURL, member string) error {
252: 	if task.Type != "change" || prURL == "" {
253: 		return nil
254: 	}
