258: 			return nil
259: 		}
260: 		return err
261: 	}
262: 	if marker.PRURL != prURL {
263: 		return nil
264: 	}
265: 	summary, err := validationSummaryFor(ctx, db, task, member)
266: 	if err != nil {
267: 		return err
268: 	}
